 3→/// The sidebar's rows: each project's sessions, newest first.
 4→pub fn rebuild(rows: &mut Vec<Row>, input: &SidebarInput) {
 5→    for project in &input.projects {
 6→        rows.clear();
 7→        rows.extend(project_rows(project, input));
 8→    }
 9→}
10→
11→/// Rows matched by key: changed ones updated in place, new ones inserted.
12→pub fn merge_by_key(rows: &mut Vec<Row>, fresh: Vec<Row>) {
13→    rows.retain(|r| fresh.iter().any(|f| f.key == r.key));
14→    for f in fresh {
15→        match rows.iter_mut().find(|r| r.key == f.key) {
16→            Some(r) => *r = f,
17→            None => rows.push(f),
18→        }
19→    }
20→}

